namespace sv_da1a15c5af7f4d69849d80823cf1aada.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

using sv_da1a15c5af7f4d69849d80823cf1aada.Models;

namespace sv_da1a15c5af7f4d69849d80823cf1aada.Services;

public class ApplicationService : IApplicationService
{
    private static int _nextId = 1000;

    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1500);
        return Interlocked.Increment(ref _nextId);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500);
        return !string.IsNullOrWhiteSpace(email)
            && email.Contains('@')
            && email.Contains('.');
    }
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps

<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex list-unstyled justify-content-between mb-0 p-0">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var isCurrent = stepIndex == CurrentStep;
            var isCompleted = stepIndex < CurrentStep;
            var isFuture = stepIndex > CurrentStep;

            <li class="step-item text-center flex-fill @(isCurrent ? "active" : "") @(isCompleted ? "completed" : "") @(isFuture ? "dimmed" : "")">
                @if (isCompleted)
                {
                    <button class="btn btn-link step-btn p-0 text-decoration-none" @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                        <span class="step-circle bg-success text-white">&#10003;</span>
                        <span class="step-label d-block mt-1 text-success fw-semibold">@StepNames[stepIndex]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white")">@(stepIndex + 1)</span>
                        <span class="step-label d-block mt-1 @(isCurrent ? "fw-semibold text-primary" : "text-muted")">@StepNames[stepIndex]</span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps
@using sv_da1a15c5af7f4d69849d80823cf1aada.Models

<h4 class="mb-3">Personal Information</h4>

<div class="mb-3">
    <label class="form-label" for="fullName">Full Name <span class="text-danger">*</span></label>
    <input id="fullName" class="form-control" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
</div>

<div class="mb-3">
    <label class="form-label" for="email">Email <span class="text-danger">*</span></label>
    <input id="email" type="email" class="form-control @(emailError is not null ? "is-invalid" : "")" @bind="Email" @bind:event="oninput" placeholder="you@example.com" />
    @if (emailError is not null)
    {
        <div class="invalid-feedback">@emailError</div>
    }
</div>

<div class="mb-3">
    <label class="form-label" for="phone">Phone <span class="text-danger">*</span></label>
    <input id="phone" type="tel" class="form-control" @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
</div>

<div class="mb-3">
    <label class="form-label" for="address">Address <span class="text-danger">*</span></label>
    <textarea id="address" class="form-control" rows="2" @bind="Address" @bind:event="oninput" placeholder="Street, City, State, ZIP"></textarea>
</div>

@if (validationError is not null)
{
    <div class="alert alert-danger">@validationError</div>
}

@if (isValidating)
{
    <div class="text-muted mb-2"><span class="spinner-border spinner-border-sm me-1"></span> Validating email…</div>
}

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@isValidating">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public string FullName { get; set; } = "";
    [Parameter, EditorRequired] public string Email { get; set; } = "";
    [Parameter, EditorRequired] public string Phone { get; set; } = "";
    [Parameter, EditorRequired] public string Address { get; set; } = "";

    [Parameter] public EventCallback<string> FullNameChanged { get; set; }
    [Parameter] public EventCallback<string> EmailChanged { get; set; }
    [Parameter] public EventCallback<string> PhoneChanged { get; set; }
    [Parameter] public EventCallback<string> AddressChanged { get; set; }

    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? validationError;
    private string? emailError;
    private bool isValidating;

    private async Task HandleNext()
    {
        validationError = null;
        emailError = null;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            validationError = "All fields are required.";
            return;
        }

        isValidating = true;
        StateHasChanged();

        var isValid = await ApplicationService.ValidateEmailAsync(Email);
        isValidating = false;

        if (!isValid)
        {
            emailError = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps
@using sv_da1a15c5af7f4d69849d80823cf1aada.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Company"
                           @onchange="e => UpdateEntry(index, entry with { Company = (string)e.Value! })" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Title"
                           @onchange="e => UpdateEntry(index, entry with { Title = (string)e.Value! })" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                           @onchange="e => UpdateEntry(index, entry with { StartDate = DateTime.Parse((string)e.Value!) })" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                           disabled="@(entry.EndDate is null && IsCurrentFlags[index])"
                           @onchange="e => UpdateEntry(index, entry with { EndDate = DateTime.Parse((string)e.Value!) })" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               checked="@IsCurrentFlags[index]"
                               @onchange="e => ToggleCurrent(index, (bool)e.Value!)" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" value="@entry.Description"
                              @onchange="e => UpdateEntry(index, entry with { Description = (string)e.Value! })"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (validationError is not null)
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter, EditorRequired] public List<bool> IsCurrentFlags { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        IsCurrentFlags.Add(false);
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        IsCurrentFlags.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void ToggleCurrent(int index, bool isCurrent)
    {
        IsCurrentFlags[index] = isCurrent;
        if (isCurrent)
        {
            Entries[index] = Entries[index] with { EndDate = null };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                validationError = "Company, Job Title, and Start Date are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps

<h4 class="mb-3">References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    var r = References[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Reference @(index + 1)</h6>
                @if (References.Count > 2)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Name <span class="text-danger">*</span></label>
                    <input class="form-control" value="@r.Name"
                           @onchange="e => UpdateReference(index, r with { Name = (string)e.Value! })" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Relationship <span class="text-danger">*</span></label>
                    <input class="form-control" value="@r.Relationship"
                           @onchange="e => UpdateReference(index, r with { Relationship = (string)e.Value! })" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" value="@r.Email"
                           @onchange="e => UpdateReference(index, r with { Email = (string)e.Value! })" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Phone <span class="text-danger">*</span></label>
                    <input type="tel" class="form-control" value="@r.Phone"
                           @onchange="e => UpdateReference(index, r with { Phone = (string)e.Value! })" />
                </div>
            </div>
        </div>
    </div>
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (validationError is not null)
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        References.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceModel updated)
    {
        References[index] = updated;
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All fields are required for each reference.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <label class="form-label" for="coverLetter">Write your cover letter</label>
    <textarea id="coverLetter" class="form-control" rows="12" maxlength="@MaxLength"
              @bind="CoverLetter" @bind:event="oninput"></textarea>
    <div class="form-text text-end">
        @CoverLetter.Length / @MaxLength characters
    </div>
</div>

@if (validationError is not null)
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<string> CoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationError;

    private async Task HandleNext()
    {
        validationError = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            validationError = "Please write a cover letter before proceeding.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps
@using sv_da1a15c5af7f4d69849d80823cf1aada.Models

<h4 class="mb-3">Review &amp; Submit</h4>

@if (IsSubmitted)
{
    <div class="alert alert-success text-center py-4">
        <h5 class="mb-2">&#10003; Application Submitted Successfully!</h5>
        <p class="mb-0">Your application ID is <strong>#@ApplicationId</strong>. We'll be in touch!</p>
    </div>
}
else
{
    <!-- Personal Info -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Personal Information</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(0)">Edit</button>
        </div>
        <div class="card-body">
            <dl class="row mb-0">
                <dt class="col-sm-3">Full Name</dt>
                <dd class="col-sm-9">@FullName</dd>
                <dt class="col-sm-3">Email</dt>
                <dd class="col-sm-9">@Email</dd>
                <dt class="col-sm-3">Phone</dt>
                <dd class="col-sm-9">@Phone</dd>
                <dt class="col-sm-3">Address</dt>
                <dd class="col-sm-9">@Address</dd>
            </dl>
        </div>
    </div>

    <!-- Work History -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>Work History</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var entry in WorkEntries)
            {
                <div class="mb-3 pb-2 border-bottom">
                    <strong>@entry.Title</strong> at @entry.Company<br />
                    <small class="text-muted">
                        @entry.StartDate.ToString("MMM yyyy") &ndash;
                        @(entry.EndDate?.ToString("MMM yyyy") ?? "Present")
                    </small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p class="mt-1 mb-0">@entry.Description</p>
                    }
                </div>
            }
        </div>
    </div>

    <!-- References -->
    <div class="card mb-3">
        <div class="card-header d-flex justify-content-between align-items-center">
            <strong>References</strong>
            <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
        </div>
        <div class="card-body">
            @foreach (var r in References)
            {
                <div class="mb-2">
                    <strong>@r.Name</strong> — @r.Relationship<br />
