@namespace sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps
@using sv_da1a15c5af7f4d69849d80823cf1aada.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    var entry = Entries[index];

    <div class="card mb-3">
        <div class="card-body">
            <div class="d-flex justify-content-between align-items-center mb-2">
                <h6 class="mb-0">Position @(index + 1)</h6>
                @if (Entries.Count > 1)
                {
                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveEntry(index)">Remove</button>
                }
            </div>

            <div class="row g-3">
                <div class="col-md-6">
                    <label class="form-label">Company <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Company"
                           @onchange="e => UpdateEntry(index, entry with { Company = (string)e.Value! })" />
                </div>
                <div class="col-md-6">
                    <label class="form-label">Job Title <span class="text-danger">*</span></label>
                    <input class="form-control" value="@entry.Title"
                           @onchange="e => UpdateEntry(index, entry with { Title = (string)e.Value! })" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">Start Date <span class="text-danger">*</span></label>
                    <input type="date" class="form-control" value="@entry.StartDate.ToString("yyyy-MM-dd")"
                           @onchange="e => UpdateEntry(index, entry with { StartDate = DateTime.Parse((string)e.Value!) })" />
                </div>
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control" value="@entry.EndDate?.ToString("yyyy-MM-dd")"
                           disabled="@(entry.EndDate is null && IsCurrentFlags[index])"
                           @onchange="e => UpdateEntry(index, entry with { EndDate = DateTime.Parse((string)e.Value!) })" />
                </div>
                <div class="col-md-4 d-flex align-items-end">
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="current-@index"
                               checked="@IsCurrentFlags[index]"
                               @onchange="e => ToggleCurrent(index, (bool)e.Value!)" />
                        <label class="form-check-label" for="current-@index">Currently working here</label>
                    </div>
                </div>
                <div class="col-12">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" rows="2" value="@entry.Description"
                              @onchange="e => UpdateEntry(index, entry with { Description = (string)e.Value! })"></textarea>
                </div>
            </div>
        </div>
    </div>
}

<button class="btn btn-outline-primary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (validationError is not null)
{
    <div class="alert alert-danger">@validationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&laquo; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &raquo;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter, EditorRequired] public List<bool> IsCurrentFlags { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
        IsCurrentFlags.Add(false);
    }

    private void RemoveEntry(int index)
    {
        Entries.RemoveAt(index);
        IsCurrentFlags.RemoveAt(index);
    }

    private void UpdateEntry(int index, WorkEntryModel updated)
    {
        Entries[index] = updated;
    }

    private void ToggleCurrent(int index, bool isCurrent)
    {
        IsCurrentFlags[index] = isCurrent;
        if (isCurrent)
        {
            Entries[index] = Entries[index] with { EndDate = null };
        }
    }

    private async Task HandleNext()
    {
        validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                validationError = "Company, Job Title, and Start Date are required for each position.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }

    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public string Description { get; set; } = "";
    }
}

