@page "/apply"
@rendermode InteractiveServer
@using sv_da1a15c5af7f4d69849d80823cf1aada.Models
@using sv_da1a15c5af7f4d69849d80823cf1aada.Components.Pages.ApplySteps
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="text-center mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep" OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@fullName" FullNameChanged="v => fullName = v"
                Email="@email" EmailChanged="v => email = v"
                Phone="@phone" PhoneChanged="v => phone = v"
                Address="@address" AddressChanged="v => address = v"
                ApplicationService="ApplicationService"
                OnNext="NextStep" />
            break;

        case 1:
            <WorkHistoryStep
                Entries="workEntries"
                IsCurrentFlags="isCurrentFlags"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 2:
            <ReferencesStep
                References="references"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 3:
            <CoverLetterStep
                CoverLetter="@coverLetter" CoverLetterChanged="v => coverLetter = v"
                OnNext="NextStep"
                OnBack="PreviousStep" />
            break;

        case 4:
            <ReviewStep
                FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                WorkEntries="workEntries"
                References="references"
                CoverLetter="@coverLetter"
                ApplicationService="ApplicationService"
                OnBack="PreviousStep"
                OnEditStep="GoToStep"
                IsSubmitted="isSubmitted"
                ApplicationId="applicationId"
                OnSubmitted="HandleSubmitted" />
            break;
    }
</div>

@code {
    private int currentStep;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryModel> workEntries = [new()];
    private List<bool> isCurrentFlags = [false];

    // Step 3 state
    private List<ReferencesStep.ReferenceModel> references = [new(), new()];

    // Step 4 state
    private string coverLetter = "";

    // Submission state
    private bool isSubmitted;
    private int? applicationId;

    private void NextStep() => currentStep++;
    private void PreviousStep() => currentStep--;

    private void GoToStep(int step)
    {
        if (step < currentStep)
        {
            currentStep = step;
        }
    }

    private void HandleSubmitted(int id)
    {
        applicationId = id;
        isSubmitted = true;
    }
}

.step-indicator .step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    font-weight: bold;
    font-size: 0.9rem;
}

.step-indicator .step-label {
    font-size: 0.8rem;
}

.step-indicator .step-item.dimmed {
    opacity: 0.5;
}

.step-indicator .step-btn {
    border: none;
    background: none;
    cursor: pointer;
}

.step-indicator .step-btn:hover .step-label {
    text-decoration: underline;
}

